#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "resident/domains/politics/politics_projection_detail.hpp"
#include "political_subordinate_appointment_intents.hpp"
#include "resident/domains/local_economy/local_economy_codec_detail.hpp"
#include "resident/domains/politics/takeover/politics_takeover_payload_guard.hpp"
#include <set>
namespace hanmo::resident::dynamic_economy_codec {
template<class A>void record(A& a,PoliticalSubordinateAppointmentIntent& i){a("id",i.id);a("appointment_policy_id",i.appointment_policy_id);a("issuer_actor_id",i.issuer_actor_id);a("candidate_actor_id",i.candidate_actor_id);a("issuer_director_policy_id",i.issuer_director_policy_id);a("candidate_director_policy_id",i.candidate_director_policy_id);}
template<class A>void record(A& a,PoliticalSubordinateAppointmentIntentCatalog& c){a("version",c.version);a("intents",c.intents);}
}
namespace hanmo::resident {namespace {
Status shape(const PoliticalSubordinateAppointmentIntentCatalog& c){if(c.version!=1||c.intents.empty()||c.intents.size()>64)return common_failure("InvalidPoliticalSubordinateIntentCatalog");std::set<std::tuple<StableId,StableId,StableId>> targets;for(const auto& row:c.intents.rows()){const auto& i=row.second;if(row.first!=i.id||i.issuer_actor_id==i.candidate_actor_id||!targets.emplace(i.appointment_policy_id,i.issuer_actor_id,i.candidate_actor_id).second)return common_failure("InvalidPoliticalSubordinateIntent",row.first);for(const auto* id:{&i.id,&i.appointment_policy_id,&i.issuer_actor_id,&i.candidate_actor_id,&i.issuer_director_policy_id,&i.candidate_director_policy_id})if(id->empty()||id->size()>4096)return common_failure("InvalidPoliticalSubordinateIntent",row.first);}return common_success();}
bool contains(const std::vector<StableId>& list,const StableId& id){return std::find(list.begin(),list.end(),id)!=list.end();}
}
Outcome<PoliticalSubordinateAppointmentIntentCatalog> decode_political_subordinate_appointment_intents(const BoundaryValue& value){auto unique=validate_political_takeover_payload(value);if(!unique.ok)return {false,{},unique.error};try{PoliticalSubordinateAppointmentIntentCatalog out;dynamic_economy_codec::decode(value,out,"/political_subordinate_appointment_intents");auto valid=shape(out);return valid.ok?Outcome<PoliticalSubordinateAppointmentIntentCatalog>{true,std::move(out),{}}:Outcome<PoliticalSubordinateAppointmentIntentCatalog>{false,{},valid.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// 原作者目录同字段直接发射，值树与无树导出不再各维护一套序列。
Status emit_political_subordinate_appointment_intents_fields(ProjectionWriter& writer,const PoliticalSubordinateAppointmentIntentCatalog& c){
 try{return dynamic_economy_codec::emit_fields(writer,c);}
 catch(const boundary::DecodeFailure& e){return writer.reject(e.error.original.code,e.error.original.path);}
}
BoundaryValue encode_political_subordinate_appointment_intents(const PoliticalSubordinateAppointmentIntentCatalog& c){return politics_projection_detail::encode_fields(c,emit_political_subordinate_appointment_intents_fields);}
Outcome<bool> read_political_subordinate_career_response(const PoliticalCareerPolicy& p,const StableId& org,const StableId& jurisdiction){if(p.response==PoliticalOfficeResponse::defer)return {false,false,common_failure("PoliticalResponseDeferred").error};if(p.response!=PoliticalOfficeResponse::accept_qualified&&p.response!=PoliticalOfficeResponse::decline)return {false,false,common_failure("InvalidPoliticalCareerPolicy",p.id).error};return {true,p.response==PoliticalOfficeResponse::accept_qualified&&contains(p.acceptable_organization_ids,org)&&contains(p.acceptable_jurisdiction_ids,jurisdiction),{}};}
Status validate_political_subordinate_appointment_intents(const PoliticalSubordinateAppointmentIntentCatalog& c,const CommonCatalog& common,const PoliticsCatalog& politics,const OrganizationCatalog& org,const PoliticalSuccessionCatalog& heads,const PoliticalSubordinateAppointmentCatalog& appointments,const PoliticalSubordinateCareerPolicyRead& read){auto valid=shape(c);if(!valid.ok)return valid;if(!read||appointments.version!=1)return common_failure("PoliticalSubordinateCareerPolicyRequired");for(const auto& row:c.intents.rows()){const auto& i=row.second;const auto* p=appointments.policies.find(i.appointment_policy_id);const auto* h=p?heads.policies.find(p->head_succession_policy_id):nullptr;const auto* j=p?politics.jurisdictions.find(p->jurisdiction_id):nullptr;const auto* office=h?org.offices.find(h->leader_office_id):nullptr;const auto* issuer=read(i.issuer_director_policy_id);const auto* candidate=read(i.candidate_director_policy_id);if(!p||!h||!j||!office||office->holder_actor_id!=std::optional<StableId>{i.issuer_actor_id}||!contains(common.actor_ids,i.issuer_actor_id)||!contains(common.actor_ids,i.candidate_actor_id)||!issuer||!candidate||issuer->id.empty()||candidate->id.empty()||issuer->staffing_posts.size()>8||candidate->maximum_travel_quote_cost<0)return common_failure("PoliticalSubordinateCareerPolicyRequired",i.id);bool permitted=false;for(const auto& post:issuer->staffing_posts)if(post.issuing_office_id==h->leader_office_id&&post.jurisdiction_id==j->id&&post.appointment_policy_id==p->appointment_policy_id&&post.candidate_actor_ids.size()<=16&&contains(post.candidate_actor_ids,i.candidate_actor_id))permitted=true;if(!permitted)return common_failure("PoliticalSubordinateStaffingPostRequired",i.id);if(candidate->response!=PoliticalOfficeResponse::defer&&candidate->response!=PoliticalOfficeResponse::accept_qualified&&candidate->response!=PoliticalOfficeResponse::decline)return common_failure("InvalidPoliticalCareerPolicy",i.id);if(candidate->response==PoliticalOfficeResponse::accept_qualified&&(candidate->acceptable_organization_ids.empty()||candidate->acceptable_jurisdiction_ids.empty()))return common_failure("PoliticalAcceptanceScopeRequired",i.id);}
return common_success();}
}
